<script lang="ts">
 import { page } from '$app/state'; import { getAssignments, submitAssignment } from '$lib/services/assignments'; import { authState } from '$lib/auth.svelte'; import { navigate } from '$lib/utils/navigation'; import type { Assignment } from '$lib/types/assignment'
 let assignment = $state<Assignment | null>(null); let text = $state(''); let error = $state(''); let saved = $state(false); const courseId = $derived(page.params.courseId as string); const assignmentId = $derived(page.params.assignmentId as string)
 $effect(() => { if (!authState.loading && !authState.user) navigate('/auth/login'); else if (!authState.loading && authState.user) load() }); async function load() { assignment = (await getAssignments(courseId)).find(a => a.id === assignmentId) ?? null }
 async function submit() { if (!assignment) return; error = ''; try { await submitAssignment({ assignmentId, text }); saved = true } catch (e) { error = e instanceof Error ? e.message : 'Unable to submit assignment' } }
</script>
<main class="container mx-auto max-w-3xl p-6">{#if assignment}<h1 class="text-2xl font-semibold">{assignment.title}</h1><p class="my-3 whitespace-pre-wrap">{assignment.instructions}</p><p class="text-sm text-muted-foreground">{assignment.points} points · Due {assignment.dueAt}</p><textarea class="mt-6 min-h-64 w-full rounded border p-3" bind:value={text} placeholder="Write your response"></textarea><button class="mt-3 rounded bg-primary px-4 py-2 text-primary-foreground" onclick={submit}>Submit</button>{#if saved}<p class="mt-3 text-green-600">Submitted.</p>{/if}{#if error}<p class="mt-3 text-destructive">{error}</p>{/if}{:else}<p>Assignment not found.</p>{/if}</main>
